public static int countOilDeposits(char[][] grid) {
    // Initialize a 2D array to keep track of the number of oil deposits in each cell
    int[][] deposits = new int[grid.length][grid[0].length];

    // Iterate over each cell in the grid
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            // If the current cell is an oil deposit, mark it as such in the deposits array
            if (grid[i][j] == '@') {
                deposits[i][j] = 1;
            }
        }
    }

    // Iterate over each cell in the grid again
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            // If the current cell is an oil deposit, update the values of its neighboring cells
            if (deposits[i][j] == 1) {
                if (i > 0) {
                    deposits[i - 1][j] = Math.max(deposits[i - 1][j], deposits[i][j]);
                }
                if (j > 0) {
                    deposits[i][j - 1] = Math.max(deposits[i][j - 1], deposits[i][j]);
                }
                if (i < grid.length - 1) {
                    deposits[i + 1][j] = Math.max(deposits[i + 1][j], deposits[i][j]);
                }
                if (j < grid[0].length - 1) {
                    deposits[i][j + 1] = Math.max(deposits[i][j + 1], deposits[i][j]);
                }
            }
        }
    }

    // Count the number of unique oil deposits
    Set<Integer> uniqueDeposits = new HashSet<>();
    for (int i = 0; i < deposits.length; i++) {
        for (int j = 0; j < deposits[0].length; j++) {
            uniqueDeposits.add(deposits[i][j]);
        }
    }

    return uniqueDeposits.size() - 1;
}

