public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the input is valid
    if (n <= 0 || start.length != 2 || end.length != 2 || paths.length != n || paths[0].length != 2) {
        return "cannot be travelled";
    }

    // Create a boolean array to keep track of the visited n-tersections
    boolean[] visited = new boolean[n];

    // Create a queue to keep track of the n-tersections to visit
    Queue<int[]> queue = new ArrayDeque<>();

    // Add the starting n-tersection to the queue
    queue.offer(start);

    // Perform a breadth-first search from the starting n-tersection
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Mark the current n-tersection as visited
        visited[current[0]][current[1]] = true;

        // Add the unvisited adjacent n-tersections to the queue
        for (int[] path : paths) {
            int nextRow = current[0] + path[0];
            int nextCol = current[1] + path[1];
            if (nextRow >= 0 && nextRow < n && nextCol >= 0 && nextCol < n && !visited[nextRow][nextCol]) {
                queue.offer(new int[] { nextRow, nextCol });
            }
        }
    }

    // If the queue is empty, then no path was found
    return "cannot be travelled";
}

