            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // create a set to store the visited n-tersections
    Set<int[]> visited = new HashSet<>();
    // add the starting n-tersection to the set
    visited.add(start);
    // create a queue to store the n-tersections to be visited
    Queue<int[]> queue = new LinkedList<>();
    // add the starting n-tersection to the queue
    queue.offer(start);
    // loop until the queue is empty
    while (!queue.isEmpty()) {
        // get the current n-tersection
        int[] current = queue.poll();
        // if the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        // loop through the paths between adjacent n-tersections
        for (int[] path : paths) {
            // if the current n-tersection is connected to the path
            if (Arrays.equals(current, path)) {
                // add the new n-tersection to the set
                visited.add(path);
                // add the new n-tersection to the queue
                queue.offer(path);
            }
        }
    }
    // if the ending n-tersection cannot be reached, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a 2D array to represent the n-teresting space
    int[][] maze = new int[n][n];

    // Fill the 2D array with the paths between adjacent n-tersections
    for (int[] path : paths) {
        maze[path[0]][path[1]] = 1;
        maze[path[1]][path[0]] = 1;
    }

    // Initialize a queue to store the current n-tersection and its distance from the starting point
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Initialize a set to keep track of the visited n-tersections
    Set<String> visited = new HashSet<>();

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue the current n-tersection and its distance from the starting point
        int[] current = queue.poll();
        int distance = current[2];

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // If the current n-tersection has been visited before, continue to the next n-tersection
        if (!visited.add(current[0] + "," + current[1])) {
            continue;
        }

        // Check if the current n-tersection has a path to an adjacent n-tersection
        for (int[] path : paths) {
            // If the current n-tersection has a path to the adjacent n-tersection, enqueue the adjacent n-tersection and its distance from the starting point
            if (current[0] == path[0] && current[1] == path[1]) {
                queue.add(new int[] { path[0], path[1], distance + 1 });
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been reached, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    Arrays.fill(visited, false);
    visited[start[0]] = true;

    Queue<Integer> queue = new LinkedList<>();
    queue.add(start[0]);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0]) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            int next = path[1];
            if (next == current) {
                if (visited[next]) {
                    return "cannot be travelled";
                }
                visited[next] = true;
                queue.add(next);
            }
        }
    }
    return "cannot be travelled";
}

