  for(int i = 0; i < nums.length; i++){
    int remainingSum = target - nums[i];
    //Check if the remaining sum is already in the hash table
    if(sumMap.containsKey(remainingSum)){
      //If it is, return the indices of the two elements
      int[] result = {i, sumMap.get(remainingSum)};
      return result;
    }
    //If it's not, add the current element to the hash table
    else {
      sumMap.put(nums[i], i);
    }
  }
  //If no two elements add up to the given target, return an empty array
  return new int[0];
}

public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;

    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[left] <= nums[mid]) {
            if (target < nums[mid] && target >= nums[left]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

