public double trimMean(int[] arr) {
    int size = arr.length;
    int lowerBound = size / 20;
    int upperBound = size - lowerBound;

    Arrays.sort(arr);
    int[] trimmedArray = Arrays.copyOfRange(arr, lowerBound, upperBound);
    double sum = 0;
    for (int i = 0; i < trimmedArray.length; i++) {
        sum += trimmedArray[i];
    }
    return sum / trimmedArray.length;
}

public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int l = (int) Math.floor(n * 0.05);
    int r = n - l - 1;
    int sum = 0;
    for (int i = l; i <= r; i++) {
        sum += arr[i];
    }
    return sum / (double) (r - l + 1);
}

