public boolean canArrange(int[] arr, int k) {
    for (int i = 0; i < arr.length / 2; i++) {
        int sum = arr[i] + arr[arr.length - 1 - i];
        if (sum % k != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] counts = new int[k];
    for (int i = 0; i < n / 2; i++) {
        int a = arr[i];
        int b = arr[n - i - 1];
        counts[a % k]++;
        counts[b % k]++;
    }
    for (int i = 0; i < k; i++) {
        if (counts[i] % 2 == 1) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
