    for (int i = 0; i < n; i++) {
        int num = arr[i] % k;
        if (count[num] % 2 == 1) return false;
        count[num]++;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time required to collect all apples at node 0
    int minTime = 0;
    // Create a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];
    // Create a queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();
    // Mark the starting node as visited
    visited[0] = true;
    // Enqueue the starting node
    queue.add(0);

    while (!queue.isEmpty()) {
        // Dequeue a node from the queue
        int node = queue.poll();
        // If the current node has an apple, add 2 to the minimum time
        if (hasApple[node]) {
            minTime += 2;
        }
        // Iterate through the edges of the current node
        for (int[] edge : edges) {
            // If the destination node has not been visited, mark it as visited and enqueue it
            if (!visited[edge[1]]) {
                visited[edge[1]] = true;
                queue.add(edge[1]);
            }
        }
    }

    // If not all nodes have been visited, return -1
    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            return -1;
        }
    }

    // Return the minimum time required to collect all apples and return to node 0
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[][] graph = new int[n][n];
    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        graph[u][v] = 1;
        graph[v][u] = 1;
    }

    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;

    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);

    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int i = 0; i < n; i++) {
            if (graph[node][i] == 1 && dist[i] > dist[node] + 1) {
                dist[i] = dist[node] + 1;
                queue.offer(i);
            }
        }
    }

    int time = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            time += dist[i];
        }
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < edges.length; j++) {
            int[] edge = edges[j];
            if (dist[edge[0]] != Integer.MAX_VALUE) {
                dist[edge[1]] = Math.min(dist[edge[1]], dist[edge[0]] + 1);
            }
        }
    }

    int time = 0;
    for (int i = 0; i < hasApple.length; i++) {
        if (hasApple[i]) {
            time += dist[i];
        }
    }

    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] appleCounts = new int[n];
    int[] depths = new int[n];
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            appleCounts[i]++;
        }
        depths[i] = 1;
    }

    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        appleCounts[u] += appleCounts[v];
        depths[v] = Math.max(depths[u] + 1, depths[v]);
    }

    int maxDepth = 0;
    for (int i = 0; i < n; i++) {
        maxDepth = Math.max(maxDepth, depths[i]);
    }

    int totalApples = 0;
    for (int i = 0; i < n; i++) {
        totalApples += appleCounts[i];
    }

    return maxDepth * (totalApples + 1);
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] parents = new int[n];
    for (int i = 0; i < n; i++) {
        parents[i] = -1;
    }
    for (int[] edge : edges) {
        int from = edge[0];
        int to = edge[1];
        parents[to] = from;
    }
    int time = 0;
    if (hasApple[0]) {
        time++;
    }
    for (int i = 1; i < n; i++) {
        int node = i;
        while (parents[node] != -1) {
            time++;
            node = parents[node];
        }
        if (hasApple[node]) {
            time++;
        }
    }
    return time;
}

public static String sortString(String s) {
      // Sort the characters in the string and store them in an array
      char[] chars = s.toCharArray();
      Arrays.sort(chars);

      // Loop through the array and build the result string
      String result = "";
      int i = 0;
      while (i < chars.length) {
        // Find the smallest character in the remaining array
        char smallest = chars[i];
        int smallestIndex = i;
        for (int j = i + 1; j < chars.length; j++) {
          if (chars[j] < smallest) {
            smallest = chars[j];
            smallestIndex = j;
          }
        }

        // Find the largest character in the remaining array
        char largest = chars[i];
        int largestIndex = i;
        for (int j = i + 1; j < chars.length; j++) {
          if (chars[j] > largest) {
            largest = chars[j];
            largestIndex = j;
          }
        }

        // Add the smallest character to the result string
        result += smallest;

        // Add the largest character to the result string
        result += largest;

        // Remove the smallest and largest characters from the array
        chars[smallestIndex] = chars[chars.length - 1];
        chars[largestIndex] = chars[chars.length - 1];
        chars = Arrays.copyOf(chars, chars.length - 2);
        i++;
      }

      return result;
    }

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    while (chars.length > 0) {
        char smallest = chars[0];
        char largest = chars[chars.length - 1];
        result.append(smallest);
        chars = Arrays.copyOfRange(chars, 1, chars.length);
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] > smallest && chars[i] < largest) {
                char temp = chars[i];
                chars[i] = smallest;
                smallest = temp;
                break;
            }
        }
        result.append(largest);
        chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
        for (int i = chars.length - 1; i >= 0; i--) {
            if (chars[i] < largest && chars[i] > smallest) {
                char temp = chars[i];
                chars[i] = largest;
                largest = temp;
                break;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    String result = "";
    while (s.length() > 0) {
        char min = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < min) {
                min = s.charAt(i);
            }
        }
        result += min;
        s = s.replace(String.valueOf(min), "");
    }
    return result;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char smallest = s.charAt(i);
        for (int j = i + 1; j < s.length(); j++) {
            if (s.charAt(j) < smallest) {
                smallest = s.charAt(j);
            }
        }
        result.append(smallest);
        for (int j = i + 1; j < s.length(); j++) {
            if (s.charAt(j) > smallest && s.charAt(j) < s.charAt(j + 1)) {
                smallest = s.charAt(j);
            }
        }
        result.append(smallest);
        for (int j = s.length() - 1; j >= 0; j--) {
            if (s.charAt(j) > smallest) {
                smallest = s.charAt(j);
            }
        }
        result.append(smallest);
        for (int j = s.length() - 1; j >= 0; j--) {
            if (s.charAt(j) < smallest && s.charAt(j) > s.charAt(j - 1)) {
                smallest = s.charAt(j);
            }
        }
        result.append(smallest);
    }
    return result.toString();
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder sb = new StringBuilder();
    while (chars.length > 0) {
        // Pick the smallest character
        char smallest = chars[0];
        sb.append(smallest);
        // Remove the smallest character
        chars = Arrays.copyOfRange(chars, 1, chars.length);
        // Pick the smallest character that is greater than the last appended character
        smallest = findNextSmallest(chars, smallest);
        while (smallest != '\u0000') {
            sb.append(smallest);
            chars = Arrays.copyOfRange(chars, 1, chars.length);
            smallest = findNextSmallest(chars, smallest);
        }

        // Pick the largest character
        char largest = chars[chars.length - 1];
        sb.append(largest);
        // Remove the largest character
        chars = Arrays.copyOfRange(chars, 0, chars.length - 1);
        // Pick the largest character that is smaller than the last appended character
        largest = findNextLargest(chars, largest);
        while (largest != '\u0000') {
            sb.append(largest);
            chars = Arrays.copyOfRange(chars, 1, chars.length);
            largest = findNextLargest(chars, largest);
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    double total = 0;
    for (int num : nums) {
        total += num;
    }
    double avg = total / nums.length;
    int sum1 = 0;
    int sum2 = 0;
    for (int i = 0; i < nums.length; i++) {
        if (i % 2 == 0) {
            sum1 += nums[i];
        } else {
            sum2 += nums[i];
        }
    }
    return sum1 / (nums.length / 2) == avg && sum2 / (nums.length / 2) == avg;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length == 0) return false;
    double total = 0;
    for (int num : nums) total += num;
    double avg = total / nums.length;
    double leftSum = 0;
    int leftLength = 0;
    for (int i = 0; i < nums.length; i++) {
        leftSum += nums[i];
        if (leftSum >= avg) {
            double rightSum = total - leftSum;
            int rightLength = nums.length - leftLength - 1;
            return leftLength > 0 && rightLength > 0 && leftSum / leftLength == rightSum / rightLength;
        }
        leftLength++;
    }
    return false;
}

