    }
    int avg = sum / nums.length;
    int leftSum = 0;
    int rightSum = 0;
    int leftSize = 0;
    int rightSize = nums.length;
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] < avg) {
            leftSum += nums[i];
            leftSize++;
        } else {
            rightSum += nums[i];
            rightSize--;
        }
        if (leftSum == rightSum && leftSize == rightSize) {
            return true;
        }
    }
    return false;
}

