}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = 0, dp1 = 0;
    for (int i = 0; i < n; i++) {
        int temp = dp0;
        dp0 = Math.min(dp0, dp1) + cost[i];
        dp1 = temp;
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = cost[0];
    int dp1 = cost[1];
    for (int i = 2; i < n; i++) {
        int dp2 = Math.min(dp0, dp1) + cost[i];
        dp0 = dp1;
        dp1 = dp2;
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int length = cost.length;
    if (length == 0) {
        return 0;
    } else if (length == 1) {
        return cost[0];
    } else if (length == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int[] dp = new int[length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[length - 1], dp[length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    dp[2] = cost[0] + cost[1];

    for (int i = 3; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

