    for(int i=0; i<n; i++){
        arr[i] = (2*i) + 1;
    }
    int count = 0;
    while(true){
        boolean allEqual = true;
        for(int i=0; i<n-1; i++){
            if(arr[i] != arr[i+1]){
                allEqual = false;
                break;
            }
        }
        if(allEqual) break;
        int min = Integer.MAX_VALUE;
        for(int i=0; i<n-1; i++){
            int diff = arr[i] - arr[i+1];
            if(diff > 0 && diff < min){
                min = diff;
            }
        }
        for(int i=0; i<n-1; i++){
            if(arr[i] > arr[i+1]){
                arr[i] -= min;
                arr[i+1] += min;
            }
        }
        count++;
    }
    return count;
}

