public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] dp = new int[n];
    List<Integer> indices = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        if (indices.isEmpty() || s.charAt(i) != s.charAt(indices.get(indices.size() - 1))) {
            dp[i] = 1;
            indices.add(i);
        } else {
            int index = indices.get(indices.size() - 1);
            indices.set(indices.size() - 1, i);
            dp[i] = dp[index] + 1;
        }
    }
    return Collections.max(dp);
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] dp = new int[n + 1];
    int[][] nextPos = new int[26][n];
    for (int i = 0; i < n; i++) {
        nextPos[s.charAt(i) - 'a'][i] = i + 1;
    }
    for (int i = 0; i < n; i++) {
        dp[i] = 1;
        for (int j = 0; j < 26; j++) {
            if (nextPos[j][i] != 0) {
                dp[i] = Math.max(dp[i], dp[nextPos[j][i] - 1] + 1);
            }
        }
    }
    return dp[n - 1];
}

