public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] length = new int[n + 1];
    int[] count = new int[n];
    int[] res = new int[n + 1];

    for (int i = 1; i <= n; i++) {
        length[i] = i;
        count[i - 1] = 1;
        for (int j = 0; j < i - 1; j++) {
            if (s.charAt(j) == s.charAt(i - 1)) {
                length[i] = Math.max(length[i], length[j] + 1);
                count[i - 1] = Math.max(count[i - 1], count[j]);
            }
            res[i] = Math.max(res[i], res[j] + count[i - 1]);
        }
    }

    return res[n];
}

