public String getSmallestString(int n, int k) {
    // Check that n is greater than 0
    if (n <= 0) {
        throw new IllegalArgumentException("n must be greater than 0");
    }

    // Check that k is greater than 0
    if (k <= 0) {
        throw new IllegalArgumentException("k must be greater than 0");
    }

    // Initialize an array to store the characters of the string
    char[] string = new char[n];

    // Initialize a variable to store the current value of the string
    int currentValue = 0;

    // Iterate through each character of the string and set it to the character
    // that corresponds to the least significant digit of the value of the
    // string so far, taking the value of the string into account
    for (int i = n - 1; i >= 0; i--) {
        // Get the least significant digit of the value of the string
        int digit = k % 26;

        // Convert the digit to a character from the alphabet
        char character = (char) ('a' + digit);

        // Set the character of the string to the corresponding character
        string[i] = character;

        // Remove the least significant digit from the value of the string
        k = k / 26;
    }

    // Return the string
    return new String(string);
}

