}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] freq = new int[n+1];
    int[] count = new int[n+1];
    int result = 0;

    // Count the frequency of each element in the array
    for (int i = 0; i < n; i++) {
        freq[A[i]]++;
    }

    // Calculate the number of permutations for each element
    for (int i = 0; i < n; i++) {
        count[A[i]] += freq[i] * (freq[i]-1) / 2;
    }

    // Combine the permutations for each element
    for (int i = 1; i <= n; i++) {
        result += count[i] * (count[i]-1) / 2;
    }

    return result;
}

