public static int findSmallestInteger(int n) {
    if (n < 10) {
        return -1;
    }
    int smallest = Integer.MAX_VALUE;
    for (int i = 1; i <= 9; i++) {
        int temp = n;
        int count = 0;
        while (temp > 0) {
            int digit = temp % 10;
            if (digit == i) {
                count++;
            }
            temp /= 10;
        }
        if (count == 0) {
            continue;
        }
        int[] digits = new int[count];
        int[] tempDigits = new int[9];
        temp = n;
        count = 0;
        while (temp > 0) {
            int digit = temp % 10;
            if (digit != i) {
                tempDigits[count++] = digit;
            }
            temp /= 10;
        }
        Arrays.sort(tempDigits, 0, count);
        for (int j = 0; j < count; j++) {
            digits[j] = tempDigits[j];
        }
        int rearranged = 0;
        for (int j = 0; j < count; j++) {
            rearranged = rearranged * 10 + digits[j];
        }
        if (rearranged < smallest) {
            smallest = rearranged;
        }
    }
    return smallest == Integer.MAX_VALUE ? -1 : smallest;
}

