    int[] y = new int[4];
    for (int i = 0; i < 3; i++) {
        x[i] = points[i][0];
        y[i] = points[i][1];
    }
    x[3] = x[0];
    y[3] = y[0];
    for (int i = 0; i < 3; i++) {
        if (x[i] == x[i+1] && y[i] == y[i+1]) return false;
    }
    int s = 0;
    for (int i = 0; i < 4; i++) {
        s += (x[i] * y[i+1]) - (x[i+1] * y[i]);
    }
    return s == 0;
}

