public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        if (i % 10 == 0) {
            result.add(i);
            continue;
        }
        int prevDigit = i % 10;
        int nextDigit = (i / 10) % 10;
        if (prevDigit >= nextDigit) {
            result.add(i);
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> (a + "" + b).compareTo(b + "" + a));
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> list = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        list.add(i);
    }
    Collections.sort(list, new Comparator<Integer>() {
        @Override
        public int compare(Integer a, Integer b) {
            return a.toString().compareTo(b.toString());
        }
    });
    return list;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int num = i;
        while (num > 0) {
            result.add(num % 10);
            num /= 10;
        }
    }
    Collections.sort(result);
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        boolean added = false;
        for (int j = 0; j < result.size(); j++) {
            if (i < result.get(j)) {
                result.add(j, i);
                added = true;
                break;
            }
        }
        if (!added) {
            result.add(i);
        }
    }
    return result;
}

